import {PROGRAMS,PHASES,FOCUSES,ACTIONS,EVENTS,SOURCES} from './data.js';
import {BBA_MAJORS,SOCIETIES,EXCHANGE_DESTINATIONS,INDUSTRIES,PLACEMENTS,secondaryOptions} from './business.js';
import * as E from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='hku-a-life-business-v2',ARCHIVE='hku-a-life-business-archive-v2';let state=null,category='All',expanded=false,view='play',saved=true,modalType='',toastTimer;
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.version===2&&PROGRAMS.some(p=>p.id===raw.program)&&['intro','plan','event','reaction','results','ending'].includes(raw.status)&&Array.isArray(raw.log)&&raw.plan&&Number.isFinite(raw.rng))state=E.upgradeLife(raw);}catch{}
let archive=[];try{archive=JSON.parse(localStorage.getItem(ARCHIVE))||[];if(!Array.isArray(archive))archive=[];archive=archive.filter(x=>x.version===2&&PROGRAMS.some(p=>p.id===x.program)).map(E.upgradeLife);}catch{}
const cash=n=>'HK$'+Math.round(n).toLocaleString('en-HK');
function save(){try{if(state&&view!=='archive')localStorage.setItem(KEY,JSON.stringify(state));saved=true;}catch{saved=false;}if(state?.status==='ending'&&view!=='archive'&&!archive.some(x=>x.seed===state.seed&&x.turn===state.turn)){archive.unshift(JSON.parse(JSON.stringify(state)));archive=archive.slice(0,12);try{localStorage.setItem(ARCHIVE,JSON.stringify(archive));}catch{saved=false;}}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),3600);}
function campus(){return `<svg viewBox="0 0 560 490" role="img" aria-label="An original illustration of a red-brick university building, green hills and Hong Kong towers"><defs><pattern id="brick" width="18" height="12" patternUnits="userSpaceOnUse"><path d="M0 0H18M0 12H18M9 0V6M0 6H18M0 6V12M18 6V12" stroke="#b98269" stroke-width=".65" fill="none"/></pattern><g id="window"><path d="M0 27V9a9 9 0 0 1 18 0v18Z" fill="#eee8d6"/><path d="M4 25V10a5 5 0 0 1 10 0v15Z" fill="#4c6961"/><path d="M9 5V25M4 14h10" stroke="#c3c9ad" stroke-width="1"/></g><g id="tree"><path d="M0 0v86" stroke="#687b60" stroke-width="4"/><ellipse cy="-9" rx="25" ry="40" fill="#9bad84"/><ellipse cx="-12" cy="4" rx="19" ry="30" fill="#839a74"/></g></defs><circle cx="278" cy="235" r="194" fill="#e6eadc"/><circle cx="413" cy="117" r="31" fill="#dcb87e" opacity=".65"/><path d="M55 304Q140 147 229 232T502 235V389H55Z" fill="#c5d0b3"/><path d="M70 310Q177 211 267 281T496 270V397H70Z" fill="#b2c19f"/><g fill="#becbbb"><path d="M97 213h21v106H97ZM121 190h34v133h-34ZM157 226h22v102h-22ZM427 181h31v144h-31ZM463 218h26v110h-26Z"/><path d="M433 170h19v11h-19Z"/></g><g stroke="#dfe5d4" stroke-width="2"><path d="M106 226v83M132 204v108M144 204v108M437 196v115M448 196v115M472 231v80"/></g><path d="M49 403Q277 375 511 407L497 421H65Z" fill="#c5c3ab"/><path d="M245 382h60l87 69H162Z" fill="#e1d3b9"/><path d="M265 387h20l51 64h-88Z" fill="#ebdfc8"/><g><path d="M125 260h309v126H125Z" fill="#b66f54"/><path d="M125 260h309v126H125Z" fill="url(#brick)"/><path d="M118 258l16-20h291l18 20Z" fill="#677b68"/><path d="M121 260h316v7H121Z" fill="#e8d5b2"/><path d="M124 313h312v7H124Z" fill="#e5d0ac"/><path d="M122 380h314v9H122Z" fill="#bbaa8b"/><path d="M220 221h120v165H220Z" fill="#c38062"/><path d="M220 221h120v165H220Z" fill="url(#brick)"/><path d="M211 224l69-41 69 41Z" fill="#e6d1ac"/><path d="M228 219l52-30 53 30Z" fill="#ad674e"/><circle cx="280" cy="208" r="9" fill="#eee4cb"/><path d="M280 202v6l5 3" fill="none" stroke="#606a57" stroke-width="1.5"/><path d="M214 225h131v7H214Z" fill="#eee0bf"/><path d="M255 377v-40a25 25 0 0 1 50 0v40Z" fill="#e9d7b3"/><path d="M261 380v-40a19 19 0 0 1 38 0v40Z" fill="#405c51"/><path d="M280 323v55M262 347h36" stroke="#b2aa84" stroke-width="2"/><path d="M248 382h64v6h-64ZM240 389h80v5h-80ZM233 395h94v5h-94Z" fill="#ccc0a1"/><g fill="#e5cfaa"><path d="M229 246h6v137h-6ZM326 246h6v137h-6Z"/><path d="M224 240h16v7h-16ZM321 240h16v7h-16Z"/></g><use href="#window" x="142" y="276"/><use href="#window" x="175" y="276"/><use href="#window" x="142" y="333"/><use href="#window" x="175" y="333"/><use href="#window" x="366" y="276"/><use href="#window" x="400" y="276"/><use href="#window" x="366" y="333"/><use href="#window" x="400" y="333"/><use href="#window" x="253" y="259"/><use href="#window" x="290" y="259"/></g><use href="#tree" x="89" y="303"/><use href="#tree" x="474" y="316"/><use href="#tree" x="50" y="337" transform="translate(15 60) scale(.8)"/><g fill="#708c68"><ellipse cx="124" cy="391" rx="37" ry="10"/><ellipse cx="427" cy="397" rx="43" ry="12"/></g><g stroke="#586e5c" stroke-width="2" fill="none"><path d="M183 140q7-8 14 0q7-8 14 0M339 124q5-6 10 0q5-6 10 0M112 167q5-6 10 0q5-6 10 0"/></g><g><circle cx="217" cy="414" r="4" fill="#615a4b"/><path d="M211 420h12l1 14h-14Z" fill="#a65244"/><path d="M213 434v11M220 434v11" stroke="#536757" stroke-width="2"/><circle cx="350" cy="410" r="4" fill="#615a4b"/><path d="M344 417h12l1 13h-14Z" fill="#7d937b"/><path d="M346 430v12M353 430v12" stroke="#536757" stroke-width="2"/></g><path d="M192 459h180" stroke="#b6c1ac" stroke-width="1"/></svg>`;}
function avatar(s){const girl=s.gender==='Girl',skin=['#dcae88','#c99570','#bd8869'][s.seed%3];return `<svg class="avatar" viewBox="0 0 100 100" role="img" aria-label="Fictional student portrait"><circle cx="50" cy="50" r="49" fill="#d4ddc7"/>${girl?'<path d="M24 57V38q0-30 27-30q28 0 27 31v37H24Z" fill="#414a3e"/>':''}<path d="M15 100v-9q3-27 35-27t35 27v9" fill="${girl?'#ac6755':'#667f72'}"/><path d="M40 59h20v16l-10 9-10-9" fill="${skin}"/><ellipse cx="50" cy="42" rx="21" ry="27" fill="${skin}"/><path d="M28 38Q23 10 49 10Q78 10 72 38L64 26Q48 34 32 25Z" fill="#414a3e"/><circle cx="42" cy="43" r="1.4" fill="#414a3e"/><circle cx="58" cy="43" r="1.4" fill="#414a3e"/><path d="M46 56q4 3 8 0" stroke="#8d5f4b" fill="none" stroke-width="1.4"/><path d="M37 72l13 12-9 9-11-16M63 72L50 84l9 9 11-16" fill="#f0ecd9"/></svg>`;}
function header(){return `<header class="topbar"><button class="brand" data-act="home" aria-label="HKU, a life home"><span class="brand-mark">生</span><span class="wordmark">HKU, a life<small>The Business School years</small></span></button><nav class="nav" aria-label="Main navigation"><button data-act="notebook">${state?'Your notebook':'Past lives'}</button><button data-act="model">About the model ↗</button>${state?`<span class="pill save-status"><i class="dot"></i>${saved?'Saved on this device':'Saving unavailable'}</span>`:'<span class="pill red save-status">2026 INTAKE</span>'}</nav></header>`;}
function footer(){return `<footer class="footer"><span>An independent, unofficial HKU-inspired game. Every student is fictional.</span><span>Made for the lives between the lectures. <button class="textbutton" data-act="model">Sources & assumptions ↗</button></span></footer>`;}
function landing(){return `<main id="main" class="landing"><section class="hero"><div class="hero-copy"><div class="eyebrow">薄扶林 · BUSINESS SCHOOL · SEPTEMBER 2026</div><h1>One offer.<br>A thousand<br><em>possible lives.</em></h1><p class="lede">The grades got you here. What happens next?<br>Step into a randomly drawn Business School student’s shoes. Find your people, miss a deadline, change your mind.<br>Your university years are yours to live.</p><button class="primary" data-act="draw">Open your admission letter <span class="arrow">↗</span></button><div class="hero-note">A complete life in about 15–25 minutes · Play at your own pace</div><div class="settings-row"><div class="setting"><label for="market">GRADUATE JOB MARKET</label><select id="market"><option value="tight">Tight hiring</option><option value="balanced">More opportunities</option></select></div><div class="setting"><label for="rarity">LIFE’S PLOT TWISTS</label><select id="rarity"><option value="grounded">Mostly everyday life</option><option value="cinematic">A little more unexpected</option></select></div></div><p class="fine" style="margin-top:12px">Hiring and event odds are game assumptions, not measured HKU statistics.</p><button class="textbutton" data-act="catalog">Explore programmes & graduation rules ↗</button></div><div class="illustration">${campus()}<div class="stamp">A NEW CHAPTER<b>2026</b>BEGINS HERE</div><div class="illustration-caption">22.2830° N &nbsp; 114.1371° E &nbsp; · &nbsp; A PLACE TO BEGIN</div></div></section><section class="landing-rule" aria-label="How to play"><div><div class="n">01</div><h3>Twelve programmes. One beginning.</h3><p>Your background, school results, programme and circumstances are drawn together. Everyone arrives with a different story.</p></div><div><div class="n">02</div><h3>A life you help shape.</h3><p>Make room for study, people, work and rest. Each semester and break brings choices—and consequences that stay.</p></div><div><div class="n">03</div><h3>More than a graduation photo.</h3><p>A return offer, another degree, a late start, a changed direction. There is no single score for a university life.</p></div></section></main>`;}
function intro(){const s=state,p=E.program(s);return `<main id="main"><article class="intro"><div class="intro-left"><div class="eyebrow">Your 2026 admission letter</div>${avatar(s)}<h1>${esc(s.name)}<br>${esc(s.surname)}</h1><span class="pill">${s.entryAge} years old · ${s.gender} · ${esc(s.origin)}</span><p class="fine" style="margin-top:20px">LIFE NO. ${s.seed.toString(36).toUpperCase()}</p></div><div class="intro-right"><div class="eyebrow">Dear ${esc(s.name)},</div><h2>A place is waiting<br>for you.</h2><p>You have been admitted to <strong>${p.name}</strong> at HKU Business School. ${s.entryYear===3?'Your previous study brings you into Year 3. This is your first year at HKU, not your first year of tertiary education.':s.incomingCredits?'You enter Year 1 after a sub-degree, with some prior learning recognised.':'You start in Year 1, with an entire undergraduate life ahead of you.'}</p><dl class="facts"><div><dt>Entry route</dt><dd>${esc(s.routeLabel)}</dd></div><div><dt>Programme</dt><dd>${p.degree} · ${p.years} years normally</dd></div><div><dt>Starting direction</dt><dd>${esc(s.major)}</dd></div><div><dt>Your circumstances</dt><dd>${esc(s.funding)}<br>${cash(s.cash)} spending money</dd></div><div><dt>Academic background</dt><dd>${esc(s.schoolResult)}</dd></div><div><dt>Home base</dt><dd>${esc(s.housing)}<br>${s.incomingCredits?s.incomingCredits+' assumed incoming credits':'No incoming credits'}</dd></div></dl><p class="fine">Programme matching uses fictional preparation and subject strengths, not official admission cutoffs. Baseline tuition and essential living costs are already funded in this version; your wallet covers the remaining budget.</p><button class="primary full" data-act="start">Plan your arrival <span class="arrow">→</span></button><button class="textbutton" data-act="reroll" style="margin-top:15px">Draw another life ↻</button></div></article></main>`;}
function stats(){const s=state,p=E.program(s),c=E.context(s),g=E.gpa(s);return `<aside class="student-side"><section class="card student-card" aria-label="Your student and status"><div class="student-top"><div class="minirow">${avatar(s)}<div><h3>${esc(s.name)} ${esc(s.surname)}</h3><div class="student-id">LIFE ${s.seed.toString(36).toUpperCase()} · ${s.age} YEARS OLD</div></div></div><div class="programme"><strong>${p.degree}</strong> · ${esc(s.major)}<br>${c.extension?'Extended study':`Year ${c.year} of ${p.years}`}${s.leaveTerms?' · on approved leave':''}</div></div><div class="student-body"><div class="detail"><span>From</span><b>${esc(s.origin)}</b></div><div class="detail"><span>Home</span><b>${esc(s.housing)}</b></div><div class="detail"><span>Route</span><b>${s.route==='dse'?'HKDSE / JUPAS':s.entryYear===3?'Senior-year admission':'Non-JUPAS / other route'}</b></div><div class="scorepair"><div><small>${p.medical?'PROGRESSION':'CUMULATIVE GPA'}</small><strong>${p.medical?s.medYears+'/6':g===null?'—':g.toFixed(2)}</strong><div class="sub muted">${p.medical?'years completed':'out of 4.30'}</div></div><div><small>${p.medical?'ASSESSMENT':'PASSED CREDITS'}</small><strong>${p.medical?s.medResit?'Resit':'Active':s.credits}</strong><div class="sub muted">${p.medical?s.medRepeats+' repeat years':'of '+p.years*60+' in this model'}</div></div></div>${[['wellbeing','Wellbeing'],['energy','Energy'],['bonds','Connection'],['career','Career readiness']].map(([k,label])=>`<div class="stat"><div class="stat-head"><span>${label}</span><span>${Math.round(s[k])}</span></div><div class="bar" role="meter" aria-label="${label}" aria-valuenow="${Math.round(s[k])}" aria-valuemin="0" aria-valuemax="100"><i class="${s[k]<30?'low':''}" style="width:${s[k]}%"></i></div></div>`).join('')}<div class="moneyline"><span>Spending money</span><strong>${cash(s.cash)}</strong></div>${s.debt?`<p class="fine">Extra funding needed: ${cash(s.debt)}</p>`:''}${s.flags.jobOffer?'<div class="hintbox">↗ '+(s.flags.returnOffer?'Return offer':'Graduate offer')+' secured, conditional on graduation</div>':''}${s.flags.postgradOffer?'<div class="hintbox">⌕ Postgraduate offer'+(s.flags.fundedStudy?' · funded':' · funding pending')+'</div>':''}</div></section><div class="sidebar-links"><button class="textbutton" data-act="academic">Study plan ↗</button><button class="textbutton" data-act="profile">Student details ↗</button><button class="textbutton" data-act="career">Careers & offers ↗</button><button class="textbutton" data-act="campus">Societies ↗</button><button class="textbutton" data-act="cv">Personal CV ↗</button></div></aside>`;}
function journal(){const meaningful=state.log.filter(x=>!['Money','Plan'].includes(x.tag)).slice(-5).reverse();return `<aside class="journal-side"><div class="journal-heading"><h3>The little things.</h3><span>Your notebook</span></div><div class="journal">${meaningful.map(x=>`<article class="entry"><small>${esc(x.date)} · ${esc(x.tag)}</small><h4>${esc(x.title)}</h4><p>${esc(x.text.length>160?x.text.slice(0,157)+'…':x.text)}</p></article>`).join('')}</div><button class="journalmore" data-act="notebook">Read your whole story ↗</button><div class="quote">“You don’t have to become everyone you could have been.”<small>A NOTE TO YOURSELF</small></div></aside>`;}
function journeyHeader(){if(state.onboarding)return `<section class="journey-header"><div><div class="eyebrow">AUGUST 2026 · BEFORE YEAR 1 SEMESTER 1</div><h1>Before the first lecture.</h1><div class="season-note">Choose your home base and your freshers’ orientation. Your first semester comes next.</div></div><span class="pill">ARRIVAL · ${state.eventIndex+1} / 2</span></section>`;const c=E.context(state),titles=['A new term, an open page.','A little room between chapters.','Back to the hill.','The summer is yours.'];return `<section class="journey-header"><div><div class="eyebrow">${E.dateLabel(state)} · ${c.extension?'EXTENDED STUDY':'YEAR '+c.year} · ${c.p.degree}</div><h1>${titles[c.phase]}</h1><div class="season-note">${state.turn===0?'You don’t know it yet, but you’ll remember some of these days.':state.leaveTerms?'The calendar keeps moving. You are allowed to take your time.':'A few choices. Another version of your life.'}</div></div><div class="phase-strip" aria-label="Academic year phases">${['Semester 1','Winter break','Semester 2','Summer break'].map((x,i)=>`<div class="phase ${i===c.phase?'active':i<c.phase?'done':''}" ${i===c.phase?'aria-current="step"':''}>${x}</div>`).join('')}</div></section>`;}
function planner(){const s=state,c=E.context(s),selected=E.selectedActions(s),used=selected.reduce((n,a)=>n+a.time,0),cost=selected.reduce((n,a)=>n+a.cost,0);let pool=E.availableActions(s).filter(a=>category==='All'||a.category===category);if(category==='All'&&!expanded){pool=pool.filter(a=>!a.requires||a.requires(s,c)).slice(0,8);for(const a of selected)if(!pool.some(x=>x.id===a.id))pool.push(a);}return `${opportunities()}<section class="card main-card"><div class="section-label"><span class="eyebrow">01 / Make a little room</span><span class="pill">${PHASES[c.phase]}</span></div><h2>What matters this time?</h2><p class="section-intro">Choose your focus, then decide where your extra time goes. Regular classes happen automatically during an active term.</p>${s.medResit?'<div class="hintbox warn">A medical re-examination is waiting this summer. “Prepare for medical re-examination” is under Study.</div>':''}${s.leaveTerms&&c.term?'<div class="hintbox">You are on approved leave this term. Your academic progress is paused.</div>':''}<div class="focuses" role="group" aria-label="Choose your focus">${FOCUSES.map(f=>`<button class="focus ${s.plan.focus===f.id?'selected':''}" data-act="focus" data-id="${f.id}" aria-pressed="${s.plan.focus===f.id}" title="${f.desc}"><span class="symbol">${f.icon}</span>${f.name}</button>`).join('')}</div><p class="focus-desc">${FOCUSES.find(f=>f.id===s.plan.focus)?.desc||''}</p><div class="spare-plan"><label for="spare-time">Unfilled extra-time slots go to</label><select id="spare-time"><option value="rest" ${s.plan.spare==='rest'?'selected':''}>Rest & recovery</option><option value="revision" ${s.plan.spare==='revision'?'selected':''}>Extra revision</option></select><p>${esc(E.studyHint(s))}</p></div><div class="planner-head"><h3>Where will your time go?</h3><div class="budget"><span>${used}/${E.capacity(s)}</span><span class="budget-pips" aria-hidden="true">${Array.from({length:E.capacity(s)},(_,i)=>`<i class="${i<used?'filled':''}"></i>`).join('')}</span></div></div><div class="categories" role="group" aria-label="Activity categories">${['All','Study','Campus','Career','Life','World'].map(x=>`<button class="category ${category===x?'active':''}" data-act="category" data-id="${x}" aria-pressed="${category===x}">${x}</button>`).join('')}</div>${category==='Campus'?'<div class="campus-cta"><button class="secondary full" data-act="campus">Choose societies · sports, arts & more ↗</button><p>Join several groups. Each one uses its own time slot.</p></div>':''}<div class="actions">${pool.map(a=>{const chosen=s.plan.actions.includes(a.id),reason=E.actionStatus(s,a),noTime=used+a.time>E.capacity(s),noMoney=cost+a.cost>s.cash;return `<button class="action ${chosen?'selected':''} ${reason?'locked':''}" data-act="action" data-id="${a.id}" aria-pressed="${chosen}" ${reason?'aria-disabled="true"':''} title="${esc(reason||(!chosen&&noTime?'Not enough free time. Remove another activity first.':!chosen&&noMoney?'Not enough spending money.':a.desc))}"><span class="check">${chosen?'✓':''}</span><span class="action-top"><span class="symbol">${a.icon}</span><strong>${esc(a.name)}</strong></span><p>${reason||a.desc}</p><span class="meta"><span>${reason?'◇ Locked':a.time+' time '+(a.time===1?'slot':'slots')}</span><span>${a.cost?cash(a.cost):a.effects?.cash?'+'+cash(a.effects.cash):'No extra cost'}</span></span></button>`;}).join('')}</div>${category==='Career'?'<button class="textbutton" data-act="career">Choose industry, placement format & review offers ↗</button>':category==='Campus'?'<button class="textbutton" data-act="campus">Manage your societies ↗</button>':category==='World'?'<button class="textbutton" data-act="academic">Set next-year exchange preference ↗</button>':''}${category==='All'?`<button class="showall" data-act="expand">${expanded?'Show a shorter list ↑':'Explore all activities ↓'}</button>`:''}<div class="plan-end"><div class="plan-summary"><span>${used?selected.length+' '+(selected.length===1?'activity':'activities')+' · '+used+' time '+(used===1?'slot':'slots'):'Spare time becomes '+(s.plan.spare==='revision'?'extra revision.':'rest.')}</span><span>Planned cost ${cash(cost)}</span></div>${c.term&&!c.medical?`<div class="helptext">Course load: ${s.plan.load} credits${s.secondary?' · '+(s.secondary==='double'?'Second major':'Minor')+' in '+esc(s.secondarySubject):''} <button class="textbutton" data-act="academic">Edit study plan ↗</button></div>`:''}<button class="primary" data-act="commit">Live this ${c.term?'semester':'break'} <span class="arrow">→</span></button><p class="fine" style="margin-top:10px">You’ll respond to ${s.turn===0||c.term?'two life moments':'a life moment'}${s.plan.actions.some(id=>['recruit','job'].includes(id))?' and an interview':''} ${s.plan.actions.some(id=>['competition','caseinternational'].includes(id))?', plus your case competition decisions':''} before moving on. Every choice is saved on this device.</p></div></section>`;}
function eventView(){const s=state,e=E.currentEvent(s);if(!e)return '<section class="card main-card"><h2>Continue your story.</h2><button class="primary" data-act="repair">Continue →</button></section>';const icons={'First days':'✳','Where you live':'⌂','Medicine':'✚','Relationships':'♡','A consequential choice':'!','Formal review':'§','An unlikely invitation':'✦','Wellbeing':'☁'};return `<article class="card event-card"><div class="section-label"><span class="eyebrow">${esc(e.category)}</span><span class="pill">Moment ${s.eventIndex+1} / ${s.queue.length}</span></div><div class="event-icon">${icons[e.category]||'✧'}</div><h2 tabindex="-1" id="story-title">${esc(e.title)}</h2><p class="event-story">${esc(e.text)}</p><div class="choices">${e.choices.map((o,i)=>`<button class="choice" data-act="choice" data-index="${i}" ${E.eventChoiceReason(s,o)?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span><strong>${esc(o.label)}</strong><small>${esc(E.eventChoiceReason(s,o)||o.hint)}</small></span><span class="arrow">↗</span></button>`).join('')}</div></article>`;}
function effectTags(e){const names={bonds:'Connection',career:'Career readiness',academic:'Preparation',wellbeing:'Wellbeing',energy:'Energy',cash:'Money',network:'Network',knowledge:'Knowledge',research:'Research',creative:'Creativity',venture:'Business progress'};return Object.entries(e).filter(([k,v])=>names[k]&&Number.isFinite(v)&&v!==0).map(([k,v])=>`<span class="effect ${v<0?'neg':''}">${names[k]} ${v>0?'+':''}${k==='cash'?cash(v):k==='academic'?(v>0?'↑':'↓'):Number.isInteger(v)?v:v.toFixed(1)}</span>`).join('');}
function reactionView(){const r=state.reaction;return `<article class="card event-card reaction"><div class="section-label"><span class="eyebrow">A moment becomes a memory</span><span>✧</span></div><h2>${esc(r.title)}</h2><p class="event-story">${esc(r.text)}</p><div class="chosen">You chose: ${esc(r.choice)}</div><div class="effects">${effectTags(r.effects)}</div><p class="fine">Changes shown are the choice’s direct effects. Chance outcomes and later consequences are recorded in your notebook.</p><button class="primary" data-act="continue">${state.endReason?'See where this chapter ends':state.eventIndex+1<state.queue.length?'See what happens next':state.onboarding?'Begin Semester 1':'Close this chapter'} <span class="arrow">→</span></button></article>`;}
function resultsView(){const s=state,c=E.context(s),next=PHASES[(c.phase+1)%4];return `<section class="card main-card results"><div class="section-label"><span class="eyebrow">A chapter, lived</span><span>✧</span></div><h2>Some things changed.<br>Some things stayed.</h2><p class="results-lead">${c.term?'Another semester becomes part of who you are.':'A little time away can still move your life forward.'}</p>${s.notes.length?s.notes.map(n=>`<div class="result-item"><h4>${esc(n.title)}</h4><p>${esc(n.text)}</p></div>`).join(''):'<div class="result-item"><h4>Time to live a little</h4><p>Your choices changed your energy, connections and experience. Not everything meaningful becomes a line on a transcript.</p></div>'}${c.final?`<div class="hintbox">${s.readyToGraduate?'All modelled requirements completed. Review any final offers before graduating.':E.degreeChecklist(s).filter(x=>!x[1]).map(x=>esc(x[0])+': '+esc(x[2])).join('<br>')}<br><button class="textbutton" data-act="academic">Full checklist ↗</button> · <button class="textbutton" data-act="career">Review offers ↗</button></div>`:''}<button class="primary" data-act="next">${s.readyToGraduate?'Graduate & see your next chapter':'Into '+next.toLowerCase()} <span class="arrow">→</span></button><p class="fine" style="margin-top:12px">Money carries forward. A fresh time budget begins next phase.</p></section>`;}
function game(){return `<main id="main">${journeyHeader()}<div class="game-grid">${stats()}<div class="main-column">${state.status==='plan'?planner():state.status==='event'?eventView():state.status==='reaction'?reactionView():resultsView()}</div>${journal()}</div></main>`;}
function ending(){const s=state,p=E.program(s),g=E.gpa(s),grad=s.endType==='graduated';return `<main id="main" class="ending">${view==='archive'?'<div class="archive-banner">Reading a past life. <button class="textbutton" data-act="return-current">Return to your current life ↗</button></div>':''}<article><div class="ending-top"><div class="eyebrow">${grad?'THE CLASS OF '+(E.context(s).calendar+(s.turn%4>=2?1:0)):'A CHAPTER CLOSES'} · ${esc(s.name.toUpperCase())} ${esc(s.surname.toUpperCase())}</div><h1>${esc(s.ending.title)}</h1><p>${esc(s.ending.text)}</p><span class="pill">${esc(s.ending.path)}</span></div><div class="ending-body"><div class="endstats"><div><strong>${p.medical?s.medYears+'/6':g===null?'—':g.toFixed(2)}</strong><small>${p.medical?'Medical years passed':'Simulated cumulative GPA'}</small></div><div><strong>${s.internships}</strong><small>Internships completed</small></div><div><strong>${s.exchanges}</strong><small>Overseas study experiences</small></div><div><strong>${s.log.filter(x=>!['Money','Plan'].includes(x.tag)).length}</strong><small>Moments in your notebook</small></div></div><div class="enddetails"><div><h3>What you leave with.</h3><p>${grad?'<strong>'+p.degree+'</strong> · '+esc(s.major):'No completed undergraduate degree in this run.'}</p>${s.secondary?`<p>${s.secondaryCompleted?'Completed':'Not completed'} ${s.secondary==='double'?'second major':'minor'} in ${esc(s.secondarySubject)} (${E.secondaryProgress(s)} modelled credits).</p>`:''}<p>${s.gapCount?s.gapCount+' gap teaching term'+(s.gapCount>1?'s':'')+'. ':''}${s.medRepeats?s.medRepeats+' medical repeat year(s). ':''}${s.flags.transferred?'You changed your programme.':''}</p><p>Wellbeing ${Math.round(s.wellbeing)}/100 · Connection ${Math.round(s.bonds)}/100</p><p>Spending money ${cash(s.cash)}${s.debt?' · Funding gap '+cash(s.debt):''}</p></div><div><h3>What the numbers miss.</h3><p>${s.bonds>65?'You made room for people. There are familiar names in your phone who were strangers when this began.':s.bonds>40?'Some connections became part of your everyday life. Others are still waiting to deepen.':'Your circle stayed small. There is still time beyond university to find your people.'}</p><p>${s.wellbeing>65?'You reach the end with some energy for what comes next.':s.wellbeing>35?'You carried a lot. The next chapter can include more room for yourself.':'This was a demanding chapter. Recovery deserves space in the next one.'}</p></div></div><div class="endactions"><button class="secondary" data-act="notebook">Read your story ↗</button><button class="secondary" data-act="export">Download story ↓</button><button class="secondary" data-act="cv">View CV ↗</button><button class="primary" data-act="new">Live another life ↻</button></div><p class="fine" style="margin-top:17px">${s.market==='tight'?'Tight':'More-opportunity'} hiring scenario · This is the position at the end of the degree, not a later graduate-employment survey. Outcomes and probabilities are fictional assumptions.</p></div></article><div class="ending-note">You were more than the choices that worked out.<br>You were here.</div></main>`;}
function render(scroll=false){save();$('#app').innerHTML=`<div class="shell">${header()}${!state?landing():state.status==='intro'?intro():state.status==='ending'?ending():game()}${footer()}</div>`;if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,content,type=''){modalType=type;$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-act="close" aria-label="Close dialog">×</button></div><div class="modal-content">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();}
function showNotebook(){if(!state){showArchive();return;}openModal(`${esc(state.name)}’s notebook`,`<p>Every decision, result and small turning point. Your most recent memories come first.</p><div style="display:flex;gap:15px;margin-bottom:20px"><button class="secondary" data-act="export">Download story ↓</button><button class="textbutton" data-act="archive">Past lives ↗</button></div>${[...state.log].reverse().map(x=>`<article class="notebook-entry"><small>${esc(x.date)} · ${esc(x.tag)}</small><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></article>`).join('')}`,'notebook');}
function showArchive(){openModal('The lives you have lived.',archive.length?`<p>Completed stories saved in this browser. Reading one keeps your current run intact.</p>${archive.map((s,i)=>`<div class="saved-life"><div><strong>${esc(s.name)} ${esc(s.surname)} · ${E.program(s).degree}</strong><p>${esc(s.ending?.path||s.endReason)} · seed ${s.seed}</p></div><button class="secondary" data-act="read-life" data-index="${i}">Read ↗</button></div>`).join('')}`:'<p>No completed lives yet. Your first one is still unwritten.</p>','archive');}
function showProfile(){if(!state)return;const s=state,p=E.program(s);openModal('The person behind the choices.',`<div style="display:flex;gap:22px;align-items:center;margin-bottom:22px">${avatar(s)}<div><h3 style="margin:0 0 8px">${esc(s.name)} ${esc(s.surname)}</h3><p style="margin:0">${s.gender} · ${s.age} · from ${esc(s.origin)}</p></div></div><table class="model-table"><tbody>${[['Entry',s.routeLabel],['Programme',p.name+' · '+p.years+' normative years'],['Starting direction',s.major],['School profile',s.schoolResult],['Starting academic year','Year '+s.entryYear+' in 2026'],['Incoming credits',s.incomingCredits+' (assumed; excluded from GPA)'],['Family circumstances',s.funding],['Funding premise','Baseline tuition and essential living costs funded; extra expenses tracked separately'],['Housing',s.housing],['Internships',s.internships],['Overseas study',s.exchanges],['Research experience',Math.round(s.research)+'/100'],['Creative practice',Math.round(s.creative)+'/100'],['Business progress',s.venture],['Relationship',s.flags.romance?'In a relationship':'No relationship recorded'],['Hiring scenario',s.market==='tight'?'Tight hiring (fictional)':'More opportunities (fictional)'],['Life seed',s.seed]].map(([a,b])=>`<tr><th>${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table><div class="form-actions">${s.status==='plan'&&view!=='archive'?'<button class="secondary" data-act="different-path">Consider a bigger life change ↗</button>':''}<button class="secondary" data-act="new">Start a different life ↻</button></div>`,'profile');}
function opportunities(){const list=E.reminders(state),updates=E.commitments(state);return `<nav class="student-tools" aria-label="Student tools">${[['academic','▤','Study plan','Majors & exchange'],['career','↗','Careers & offers','Applications & pay'],['cv','▧','Personal CV','Your experience'],['campus','✳','Societies','Find your people'],['cases','◇','Case competitions','Teams & awards']].map(([act,icon,title,sub])=>`<button data-act="${act}" class="tool-button"><span class="tool-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</nav>${updates.length?`<div class="commitment-notice"><strong>Your plans & offers</strong><ul>${updates.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`:''}${list.length?`<details class="opportunities"><summary>Optional deadline tips <span class="pill">${list.length}</span><span class="tip-toggle">View ↓</span></summary><p class="fine">For paths you might want to explore. Choose what fits your life; your programme requirements remain in Study plan.</p><ul>${list.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}`;}

function showCatalog(){openModal('One school. Many directions.',`<p>2026-entry Business School edition: all 12 standalone undergraduate programme routes, the five BBA major choices, and permissible FBE second majors and minors. BBA(IS) is not open to new admissions. Joint engineering and international dual-degree arrangements are outside this edition.</p>${PROGRAMS.map(p=>`<article class="source"><div class="eyebrow">${p.years} YEARS · ${p.total} CREDITS</div><h3>${esc(p.degree)}</h3><p>${esc(p.name)}</p><p>${esc(p.note)}</p>${p.id==='bba'?'<p>'+BBA_MAJORS.map(esc).join(' · ')+'</p>':''}<a href="${p.source}" target="_blank" rel="noopener">2026-entry regulations & syllabus ↗</a></article>`).join('')}<p class="fine">Some 2026 documents remain marked “subject to approval.” The game checks programme-level requirements. Individual course prerequisites, selection decisions, exemptions, language arrangements and faculty approval remain simplified.</p>`,'catalog');}
function showModel(){openModal('How this edition works.',`<p>An independent, fictional HKU Business School life simulator starting in 2026. Your course of study shapes the decisions you face.</p><div class="hintbox"><strong>Real curriculum structures; fictional probabilities.</strong> Programme requirements and names come from the linked 2026 syllabuses. Outcomes, salaries, admission weights and selection thresholds are game assumptions.</div><button class="secondary" data-act="catalog">Browse all programmes & requirements ↗</button><h3>Study and GPA</h3><p>Classes, assignments and baseline revision happen automatically in active teaching terms. You explicitly send spare time to rest or extra revision. “Hit the books” plus revision and study activities prioritises academics. Preparation, fatigue, workload and chance still matter: no activity combination guarantees a grade.</p><p>The GPA is credit weighted on a 4.3 scale. 3.00–3.59 is a useful upper-second band reference; 3.60–4.30 is the first-class GGPA band in the reviewed regulations. The game’s CGPA is not an official GGPA or honours award: Common Core treatment and Board decisions can differ.</p><h3>Degree planning</h3><p>Passed six-credit model courses are assigned to university, main-major, required-track, secondary and elective buckets. The recommended timetable handles individual core courses, advanced electives, language/AI requirements and non-credit university modules in the background. Capstones and special programme requirements have separate checks. These buckets do not certify actual course-by-course completion.</p><p>Most 2026 programmes need 54 university credits (12 languages, 36 Common Core, 6 AI literacy). BGLIS uses 36 (12 languages, 24 Common Core). BBA(Law)&LLB uses 36 in its headline 300-credit structure, with English learning incorporated into law courses. Its source contains a conflicting reference-table language subtotal; the game follows the syllabus’s opening curriculum structure.</p><p>FBE second majors normally require 78 credits; AMPB and QFin require 96. The game recognises up to 24 shared faculty-core credits for a second major, and fills the degree total with electives. Minors require 36 distinct credits. Special selection uses an illustrative 3.00 screen for EDI/AMPB/QFin, not an official admission cutoff. Optional unfinished tracks do not automatically block graduation.</p><p>Declare from the summer before Year 2 through final-year Semester 1. The game locks the chosen additional subject once started. A 36-credit overload assumes permission; reduced loads, failed credits or placements may delay graduation. This edition allows four gap teaching terms and a maximum study window of 150% of the normative years, rounded to whole years; actual registration and leave approval rules differ.</p><h3>Exchange and placements</h3><p>Apply in winter for next academic year, not the current spring. The published main round for 2026–27 ran 22 Dec 2025–22 Jan 2026; future dates are approximated. No final-semester exchange is a firm rule in this game. Credit transfer is pass/fail and can fail or lose mapping approval. IBGM must complete a semester abroad and then finish at home. BGLIS has its own prescribed global modules.</p><p>Internship applications lead to interviews, then offers you can accept or decline. Summer, six-month and twelve-month placements have different pay and study delays. Named real employers are used only as fictional role examples. Their vacancies, role titles, pay, selection and return offers here are not advertised positions or company commitments. Gross pay is simplified into your wallet; taxes and detailed living costs are omitted. Work eligibility and leave approval are assumed after a fictional check.</p><h3>Hiring scenarios</h3><p>“Tight hiring” caps an individual graduate-offer threshold at 70%; the other scenario caps it at 90%. Neither is a verified HKU employment rate or a calibrated cohort result. Industry fit, skills, GPA, interviews and experience change the threshold; a fixed hidden draw prevents identical repeated applications from rerolling success. An accepted offer is conditional on completing the degree.</p><h3>Starting lives and saves</h3><p>Gender, origin, resources and preparation are fictional draws, not demographic statistics. Sub-degree graduates enter Year 1 in this edition; automatic senior-year admission and advanced standing are not assumed. Tuition and baseline essential costs have funding arranged. This browser stores the current run and 12 completed lives. The previous edition’s saves are preserved separately.</p><h3>Societies & case competitions</h3><p>Extra-time budgets are 6 slots per teaching semester, 2 in winter and 4 in summer. Full-time placements leave 1 personal slot. Multiple society memberships are allowed; each group has its own participation and committee record. Only students running a group can do its society work during breaks. Committee eligibility needs two teaching semesters in that group. International case nominations unlock through sustained HICS performance or local awards. Prior champions receive priority; selection still depends on readiness and the competing field. Three training weekends precede every sponsored trip. These selection and sponsorship rules are game assumptions.</p><h3>Sources · checked 23 October 2026</h3>${SOURCES.map(([tag,title,url,note])=>`<div class="source"><div class="eyebrow">${esc(tag)}</div><a href="${url}" target="_blank" rel="noopener">${esc(title)} ↗</a><p>${esc(note)}</p></div>`).join('')}`,'model');}
function showAcademic(){if(!state)return;const s=state,c=E.context(s),edit=s.status==='plan'&&view!=='archive',declare=edit&&(c.year>=2||c.phase===3)&&(!c.final||c.phase===0),type=s.secondary|| (c.p.mandatorySecond?'double':'minor'),subjects=secondaryOptions(s,type);if(s.secondarySubject&&!subjects.includes(s.secondarySubject))subjects.push(s.secondarySubject);openModal('Your route to graduation.',`<div class="eyebrow">${esc(c.p.degree)} · 2026 ENTRY</div><p>${esc(c.p.note)}</p><div class="audit-list">${E.degreeChecklist(s).map(([label,done,progress])=>`<div class="audit-row"><span class="audit-icon ${done?'done':''}">${done?'✓':'○'}</span><span><strong>${esc(label)}</strong><small>${esc(progress)}</small></span></div>`).join('')}</div><p class="fine">Automatic recommended courses fill these credit buckets. Individual compulsory courses, prerequisites and timetable approval are simplified; consult the <a href="${c.p.source}" target="_blank" rel="noopener">2026 programme syllabus ↗</a>.</p><h3>What does a better GPA mean?</h3><p>3.00+ is a useful upper-second band reference; 3.60+ is the first-class GGPA band in the reviewed regulations. A stronger GPA can help with some applications, but relevant experience and interviews also count. This simulated CGPA does not determine an official honours award.</p><div class="hintbox">${esc(E.studyHint(s))}</div><div class="formfield"><label for="course-load">Teaching-term load</label><select id="course-load" ${edit?'':'disabled'}>${[24,30,36].map(n=>`<option value="${n}" ${s.plan.load===n?'selected':''}>${n} credits · ${n===24?'lighter pace; likely extension':n===30?'standard':'overload; assumes permission, more fatigue'}</option>`).join('')}</select></div>${c.p.majors.length>1?`<div class="formfield"><label for="primary-major">${c.p.global?'Specialization':'Primary major / stream'}</label><select id="primary-major" ${declare&&!s.flags.majorLocked&&(!c.p.global||c.year>=3||c.year===2&&c.phase===3)?'':'disabled'}>${c.p.majors.map(x=>`<option ${s.major===x?'selected':''}>${esc(x)}</option>`).join('')}</select><p class="fine">Your initial draw is a starting preference. Make one change at declaration time. EDI selection uses a fictional 3.00 GPA screen.</p></div>`:''}<div class="formfield"><label for="secondary-type">Additional study ${c.p.mandatorySecond?'· second major compulsory':''}</label><select id="secondary-type" ${declare?'':'disabled'}>${[['','No additional track'],['minor','Minor · 36 credits'],['double','Second major · 78 or 96 credits']].map(([id,label])=>`<option value="${id}" ${s.secondary===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="formfield"><label for="secondary-subject">Permissible FBE subject</label><select id="secondary-subject" ${declare&&!s.secondary?'':'disabled'}>${subjects.length?subjects.map(x=>`<option ${s.secondarySubject===x?'selected':''}>${esc(x)}</option>`).join(''):'<option value="">No additional FBE major modelled for this programme</option>'}</select></div>${s.secondary?`<p>${esc(s.secondarySubject)}: ${E.secondaryProgress(s)} / ${E.secondaryTarget(s)} credits, including ${E.secondaryShared(s)} shared faculty-core credits.</p>`:''}<p class="fine">Declarations open in the summer before Year 2 and close after final-year Semester 1. An additional subject stays fixed once started. EDI, AMPB and QFin require selection (a 3.00 GPA game screen). ADA has no additional FBE major; BGLIS additional majors and cross-faculty tracks are not modelled.</p><h3>Plan ahead for exchange</h3>${s.exchangeBooking?`<div class="hintbox">${esc(s.exchangeBooking.city)} · ${E.dateLabel({...s,turn:s.exchangeBooking.turn})}. Apply date: ${E.dateLabel({...s,turn:s.exchangeBooking.applied})}. Budget: HK$18,000.</div>`:''}<div class="formfield"><label for="exchange-semester">Target semester in the next academic year</label><select id="exchange-semester" ${edit&&!c.p.global?'':'disabled'}><option value="0" ${s.exchangeChoice===0?'selected':''}>Semester 1 · back at HKU for Semester 2</option><option value="2" ${s.exchangeChoice===2?'selected':''}>Semester 2 · only before final year</option></select></div><div class="formfield"><label for="exchange-city">Destination preference · 26 choices</label><select id="exchange-city" ${edit&&!c.p.global?'':'disabled'}>${['Europe','Asia','Oceania','North America'].map(region=>`<optgroup label="${region}">${EXCHANGE_DESTINATIONS.filter(d=>d.region===region).map(d=>`<option value="${esc(d.id)}" ${s.exchangeCity===d.id?'selected':''}>${esc(d.id)} — ${esc(d.school)}</option>`).join('')}</optgroup>`).join('')}</select></div><p class="fine">Partner places and requirements vary by year; nominations and the HK$18,000 extra budget are simplified in this game. These settings do not submit an application. Select “Apply for next-year exchange” in World during winter. Funding, partner availability and credit mapping matter. Short overseas study never satisfies the IBGM semester requirement in this game.</p>${edit?'<button class="primary full" data-act="save-academic">Save study plan →</button>':''}<h3>Transcript</h3>${s.grades.length?`<table class="model-table"><thead><tr><th>Period</th><th>Passed / attempted</th><th>GPA</th></tr></thead><tbody>${s.grades.map(g=>`<tr><td>${esc(g.date)}</td><td>${g.passed} / ${g.attempted}</td><td>${g.pf?'P/F':g.gpa.toFixed(2)}</td></tr>`).join('')}</tbody></table>`:'<p>Your first results are ahead.</p>'}`,'academic');}
function showCareer(){if(!state)return;const s=state,edit=s.status==='plan'&&view!=='archive',decide=edit||(s.status==='results'&&s.readyToGraduate&&view!=='archive'),industry=INDUSTRIES.find(x=>x.id===s.careerTarget);openModal('Find a direction. Consider the offer.',`<p>Choose where to focus applications. Build evidence through study, projects and relevant experience; then prepare for the interview.</p><div class="formfield"><label for="career-industry">Industry focus</label><select id="career-industry" ${edit?'':'disabled'}>${INDUSTRIES.map(i=>`<option value="${i.id}" ${i.id===s.careerTarget?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div><div class="formfield"><label for="placement-type">Preferred internship format</label><select id="placement-type" ${edit?'':'disabled'}>${PLACEMENTS.map(p=>`<option value="${p.id}" ${s.placementType===p.id?'selected':''}>${p.name} · ${p.months} months · ${p.terms} teaching term(s) away</option>`).join('')}</select></div>${edit?'<button class="secondary" data-act="save-career">Save application focus ✓</button>':''}<div class="hintbox"><strong>Next step:</strong> choose “Targeted internship applications” or “Graduate applications” in Career activities. The interview arrives during the phase. Offers require a separate acceptance.</div><p class="fine">All listed vacancies, monthly gross salaries and selection outcomes are fictional examples, including at real employers. This is not a job board. Summer placements last two months; six- and twelve-month placements pause one and two teaching terms respectively. Delays to degree requirements can extend graduation further.</p>${s.placement?`<article class="offer-card"><span class="eyebrow">${E.placementActive(s)?'IN PROGRESS':'ACCEPTED · UPCOMING'}</span><h3>${esc(s.placement.company)}</h3><p>${esc(s.placement.role)} · ${s.placement.remaining} months remaining</p><p>${cash(s.placement.salary)}/month · starts ${E.dateLabel({...s,turn:s.placement.start})}</p><p>Do not schedule an exchange during this commitment.</p></article>`:''}<h3>Offers & decisions</h3>${s.offers.length?[...s.offers].reverse().map(o=>`<article class="offer-card"><div class="eyebrow">${o.returnOffer?'RETURN OFFER':o.kind==='job'?'GRADUATE ROLE':PLACEMENTS.find(p=>p.id===o.mode)?.name} · ${esc(o.status)}</div><h3>${esc(o.company)}</h3><p>${esc(o.role)}</p><div class="offer-facts"><strong>${cash(o.salary)}<small>gross / month</small></strong><strong>${o.kind==='job'?'After graduation':o.months+' months'}<small>${o.kind==='job'?'degree completion required':o.terms+' teaching term(s) on leave'}</small></strong></div>${o.kind==='intern'?`<p>Starts ${E.dateLabel({...s,turn:o.start})} · total gross pay ${cash(o.salary*o.months)} if completed.</p>`:''}${o.status==='pending'?`<p class="fine">Decide by the planning screen for ${E.dateLabel({...s,turn:o.expires})}. Compare learning, industry fit, pay and delayed graduation.</p>${decide?`<div class="form-actions"><button class="primary" data-act="accept-offer" data-id="${o.id}">Accept offer</button><button class="secondary" data-act="decline-offer" data-id="${o.id}">Decline</button></div>`:'<p>Review again when the next planning screen opens.</p>'}`:''}</article>`).join(''):'<p>No offers yet. Applying starts a process; it does not guarantee a result.</p>'}<button class="textbutton" data-act="cv">View personal CV ↗</button>`,'career');}
let societyFilter='All';
function showCampus(){if(!state)return;const s=state,edit=s.status==='plan'&&view!=='archive',used=E.selectedActions(s).reduce((n,a)=>n+a.time,0),c=E.context(s);openModal('Find your people.',`<div class="campus-summary"><strong>${used} / ${E.capacity(s)} slots planned</strong><span>${s.societies.length} active records · ${s.plan.actions.filter(id=>id.startsWith('society:')||id.startsWith('committee:')).length} groups planned</span></div><p>${c.term?'Choose any mix of groups that fits your time and spending money. Each participation activity uses 1 slot and HK$300. Memberships stay on your record even when you take a semester off.':'During winter and summer, society work is available only for a group you already run. Ordinary membership stays on your record; participation resumes in a teaching semester.'}</p><div class="categories" role="group" aria-label="Society types">${['All','Business & community','Sports','Arts & fun'].map(g=>`<button class="category ${societyFilter===g?'active':''}" data-act="society-filter" data-id="${esc(g)}" aria-pressed="${societyFilter===g}">${g}</button>`).join('')}</div><div class="society-grid">${SOCIETIES.filter(x=>societyFilter==='All'||(x.group||'Business & community')===societyFilter).map(x=>{const m=s.societies.find(m=>m.id===x.id),id='society:'+x.id,a=E.actionById(s,id),chosen=s.plan.actions.includes(id),reason=E.actionStatus(s,a),committee='committee:'+x.id,leader=E.runsSociety(m),committeeChosen=s.plan.actions.includes(committee);return `<article class="society-card ${chosen||committeeChosen?'selected':''}"><div class="eyebrow">${esc(x.area)}</div><h3>${esc(x.name)}</h3><p>${esc(x.desc)}</p>${m?`<p class="membership"><strong>${esc(m.role)}</strong> · ${E.societyTerms(m)} teaching semester(s)</p>`:''}<button class="${chosen?'primary':'secondary'} full" data-act="society-plan" data-id="${id}" aria-pressed="${chosen}" ${!edit||reason&&!chosen?'disabled':''}>${chosen?'Planned ✓ · remove':!c.term?'Organise break activities':m?'Participate this semester':'Join this semester'}${chosen?'':' · 1 slot'}</button>${reason?`<p class="fine lock-reason">${esc(reason)}</p>`:''}${c.term&&!leader&&E.societyTerms(m)>=2?`<button class="secondary full" data-act="society-plan" data-id="${committee}" aria-pressed="${committeeChosen}" ${!edit||E.actionStatus(s,E.actionById(s,committee))&&!committeeChosen?'disabled':''}>${committeeChosen?'Committee planned ✓ · remove':'Run for committee · 2 slots'}</button>`:''}${m&&!leader&&E.societyTerms(m)<2?'<p class="fine">Committee work unlocks after 2 teaching semesters with this group.</p>':''}</article>`;}).join('')}</div><button class="secondary full" data-act="cases">Explore the international case pathway ↗</button>`,'campus');}
function showCases(){if(!state)return;const s=state,r=s.caseRecord,m=s.societies.find(x=>x.id==='hics'),id='caseinternational',a=E.actionById(s,id),chosen=s.plan.actions.includes(id),reason=E.actionStatus(s,a),edit=s.status==='plan'&&view!=='archive';openModal('From campus to the world.',`<div class="case-banner"><div class="eyebrow">INTERNATIONAL CASE COMPETITIONS</div><h3>${r.unlocked?'Your pathway is open.':'Build your case experience.'}</h3><p>${r.unlocked?'You can form a team and apply once each teaching semester. Each nomination is competitive.':'Complete two teaching semesters in HICS and build case readiness to 35, or win a local business case award. Either route unlocks future nominations.'}</p><div class="case-stats"><span><b>${E.societyTerms(m)} / 2</b> HICS semesters</span><span><b>${E.caseReadiness(s)} / 100</b> case readiness</span><span><b>${r.localAwards}</b> local awards</span></div></div><p>Case readiness grows with case practice, knowledge, career preparation and HICS experience. A local award can open this route even without HICS membership.</p><ol class="case-path"><li><strong>Form your team</strong><span>Choose complementary strengths. Prior championships receive the strongest selection priority.</span></li><li><strong>Earn a nomination</strong><span>Your capability, energy and record compete against this semester’s field. Current priority: ${esc(E.casePriority(s))}.</span></li><li><strong>Train for three weekends</strong><span>Case research, financial analysis, then presentation and Q&A. Complete all three before departure.</span></li><li><strong>Represent HKU abroad</strong><span>Training, flights, accommodation and entry are fully sponsored in the game. Results and completed training appear on your CV.</span></li></ol><div class="hintbox">Reserve 3 extra-time slots for selection, training and the trip. If not selected, two reserved slots become rest. This trip is separate from semester exchange and earns no study credits.</div><button class="${chosen?'secondary':'primary'} full" data-act="case-plan" data-id="caseinternational" ${!edit||reason&&!chosen?'disabled':''}>${chosen?'International team planned ✓ · remove':'Form a team this semester · 3 slots'}</button>${reason?`<p class="fine lock-reason">${esc(reason)}</p>`:''}<button class="secondary full" data-act="case-plan" data-id="competition" ${!edit||E.actionStatus(s,E.actionById(s,'competition'))?'disabled':''}>${s.plan.actions.includes('competition')?'Local competition planned ✓ · remove':'Enter a local competition · 2 slots · HK$600'}</button><h3>Your case record</h3>${r.history.length?r.history.slice().reverse().map(h=>`<div class="cv-entry"><strong>${esc(h.kind)} · ${esc(h.result)}</strong><small>${esc(h.date)}${h.city?' · '+esc(h.city):''}</small></div>`).join(''):'<p>Your first competition is ahead of you.</p>'}<p class="fine">Selection thresholds, sponsorship and this training sequence are game rules. Invitational locations and results are fictional.</p>`,'cases');}

function cvText(){const s=state,p=E.program(s);return `${s.name} ${s.surname}\nFICTIONAL STUDENT CV · HKU, A LIFE\n\nEDUCATION\nHKU Business School · ${p.degree} · ${s.major}\n2026 entry · ${s.endType==='graduated'?'Graduated':'Year '+E.context(s).year+'; graduation subject to requirements'}\nCGPA: ${E.gpa(s)?.toFixed(2)||'Not yet assessed'} / 4.30\n${s.secondary?(s.secondary==='double'?'Second major':'Minor')+': '+s.secondarySubject+' ('+(s.secondaryCompleted?'completed':'in progress')+')\n':''}\nCOMPLETED EXPERIENCE\n${s.experience.length?s.experience.map(w=>`${w.company} · ${w.role}\n${w.months} months · completed ${w.completed}`).join('\n\n'):'No completed placements yet.'}\n\nCAMPUS & PROJECTS\n${s.societies.map(m=>m.name+' · '+m.role+' · '+m.terms+' phase(s)').join('\n')}\n${s.achievements.map(a=>a.date+' · '+a.title+'\n'+a.detail).join('\n')}\n\nNEXT COMMITMENT\n${s.job?s.job.company+' · '+s.job.role+' (accepted, conditional on graduation)':s.placement?s.placement.company+' · '+s.placement.role+' ('+(E.placementActive(s)?'in progress':'upcoming')+')':'No accepted commitment'}\n\nAll people, work experience, offers and salary figures are simulated. This is a game record, not a real job application.`;}
function showCV(){if(!state)return;const s=state,p=E.program(s);openModal(`${esc(s.name)}’s personal CV.`,`<article class="cv"><div class="cv-heading"><div><h2>${esc(s.name)} ${esc(s.surname)}</h2><p>HKU Business School · ${esc(INDUSTRIES.find(x=>x.id===s.careerTarget)?.name)} interests</p></div><span class="pill">FICTIONAL STUDENT</span></div><h3>Education</h3><strong>${esc(p.degree)} · ${esc(s.major)}</strong><p>2026 entry · ${s.endType==='graduated'?'Graduated':`Year ${E.context(s).year} of ${p.years}; completion subject to requirements`}<br>CGPA ${E.gpa(s)?.toFixed(2)||'—'} / 4.30 · ${s.credits} credits passed</p>${s.secondary?`<p>${s.secondary==='double'?'Second major':'Minor'}: ${esc(s.secondarySubject)} · ${E.secondaryProgress(s)}/${E.secondaryTarget(s)} credits (${s.secondaryCompleted?'completed':'in progress'})</p>`:''}<h3>Completed experience</h3>${s.experience.length?s.experience.map(w=>`<div class="cv-entry"><strong>${esc(w.company)} · ${esc(w.role)}</strong><small>${w.months} months · completed ${esc(w.completed)}</small><p>Completed a ${PLACEMENTS.find(p=>p.id===w.mode).name.toLowerCase()} in ${esc(INDUSTRIES.find(i=>i.id===w.industry).name)}.</p></div>`).join(''):'<p>No completed placements yet.</p>'}${s.placement?`<div class="hintbox">${E.placementActive(s)?'In progress':'Upcoming'}: ${esc(s.placement.company)} · ${esc(s.placement.role)}. Not yet counted as completed experience.</div>`:''}<h3>Campus & leadership</h3>${s.societies.length?s.societies.map(m=>`<div class="cv-entry"><strong>${esc(m.name)}</strong><small>${esc(m.role)} · ${E.societyTerms(m)} teaching semesters · ${m.terms} total activity phases</small></div>`).join(''):'<p>No society participation recorded.</p>'}<h3>Projects & global learning</h3>${s.achievements.map(a=>`<div class="cv-entry"><strong>${esc(a.title)}</strong><small>${esc(a.date)}</small><p>${esc(a.detail)}</p></div>`).join('')||'<p>No completed project or exchange entries yet.</p>'}${s.globalModules.length?'<p>BGLIS modules: '+s.globalModules.map(esc).join(', ')+'</p>':''}${s.job?`<h3>Accepted next step</h3><p>${esc(s.job.company)} · ${esc(s.job.role)}<br>Conditional on graduation · fictional offer</p>`:''}</article><button class="secondary" data-act="download-cv">Download CV record ↓</button><p class="fine">This CV records what happened in the game. It does not invent project impact or claim uncompleted work.</p>`,'cv');}

function newModal(){openModal('Another beginning.',`<p>${state&&state.status!=='ending'?'Starting a new life replaces the current unfinished run on this device. Your completed lives remain in Past lives.':'Draw a different student, with a different starting point.'}</p><div class="formfield"><label for="new-market">Graduate job market</label><select id="new-market"><option value="tight">Tight hiring · fictional scenario</option><option value="balanced">More opportunities · fictional scenario</option></select></div><div class="formfield"><label for="new-rarity">Plot twists</label><select id="new-rarity"><option value="grounded">Mostly everyday life</option><option value="cinematic">A little more unexpected</option></select></div><div class="formfield"><label for="new-seed">Optional life seed · replay a beginning</label><input id="new-seed" type="number" min="0" max="4294967295" placeholder="Leave blank for a random life"></div><p class="fine">The same seed, scenario and choices reproduce the same life. Different choices open different branches.</p><div class="form-actions"><button class="primary" data-act="confirm-new">Draw a new life ↗</button><button class="secondary" data-act="close">Keep this life</button></div>`,'new');}
function download(){if(!state)return;const summary=E.lifeSummary(state);const text=`HKU, A LIFE\n${summary.name}\n${summary.programme} · ${summary.major}\n${summary.entry}\nLife seed: ${summary.seed}\nOutcome: ${summary.outcome}\n${E.program(state).medical?'Medical years passed: '+summary.medicalYears:'Simulated GPA: '+(summary.gpa?.toFixed(2)||'Not yet assessed')}\n\nFictional simulation. Game assumptions are not HKU statistics.\n\n`+summary.journal.map(x=>`${x.date} · ${x.tag}\n${x.title}\n${x.text}`).join('\n\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`HKU-a-life-${state.name}-${state.seed}.txt`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your story has been downloaded.');}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('change',e=>{if(!state||state.status!=='plan')return;if(e.target.id==='spare-time'){state.plan.spare=e.target.value;render();}if(e.target.id==='secondary-type'){const subject=$('#secondary-subject'),options=secondaryOptions(state,e.target.value);subject.innerHTML=options.map(x=>`<option>${esc(x)}</option>`).join('');subject.disabled=!!state.secondary;}});
let currentBeforeArchive=null;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;switch(act){
 case 'home':if(state)newModal();else window.scrollTo({top:0,behavior:'smooth'});return;
 case 'model':showModel();return;
 case 'close':closeModal();return;
 case 'notebook':showNotebook();return;
 case 'archive':showArchive();return;
 case 'profile':showProfile();return;
 case 'academic':showAcademic();return;
 case 'catalog':showCatalog();return;
 case 'career':showCareer();return;
 case 'campus':showCampus();return;
 case 'cases':showCases();return;
 case 'society-filter':societyFilter=b.dataset.id;showCampus();return;
 case 'society-plan':case 'case-plan':{const a=E.actionById(state,b.dataset.id);if(!E.toggleAction(state,a.id)){toast(E.actionStatus(state,a)||'Not enough time or spending money. Remove an activity to make room.');return;}const scroll=$('#modal').scrollTop;render();if(act==='case-plan')showCases();else showCampus();$('#modal').scrollTop=scroll;return;}
 case 'cv':showCV();return;
 case 'download-cv':downloadText(cvText(),`HKU-CV-${state.name}-${state.seed}.txt`);return;
 case 'society-target':if(state.status==='plan'){state.societyTarget=b.dataset.id;render();showCampus();}return;
 case 'save-career':if(state.status==='plan'){state.careerTarget=$('#career-industry').value;state.placementType=$('#placement-type').value;closeModal();render();toast('Focus saved. Select an application activity to apply.');}return;
 case 'accept-offer':if(!E.acceptOffer(state,b.dataset.id)){toast('Cannot accept: resolve another placement, exchange conflict, expired start or leave limit first.');return;}render();showCareer();return;
 case 'decline-offer':E.declineOffer(state,b.dataset.id);render();showCareer();return;
 case 'export':download();return;
 case 'new':newModal();return;
 case 'different-path':openModal('Stay, pause, or change direction.', '<p>You can consider leaving university for reasons beyond grades or work. A gap preserves the possibility of returning. Withdrawal ends this run without a degree. You will choose explicitly on the next screen.</p><div class="formfield"><label for="exit-motive">What needs more room in this life?</label><select id="exit-motive"><option value="wellbeing and recovery">Wellbeing and recovery</option><option value="family responsibilities">Family responsibilities</option><option value="a business idea">A business idea</option><option value="creative work">Creative work</option><option value="other personal priorities">Other personal priorities</option></select></div><button class="primary full" data-act="explore-exit">Explore the options →</button>', 'change');return;
 case 'explore-exit':if(state.status!=='plan')return;state.flags.exitMotive=$('#exit-motive').value;state.flags.resumePlanAfterExit=true;state.queue=['exitdecision'];state.eventIndex=0;state.status='event';state.notes=[];state.termAcademic=0;closeModal();break;
 case 'draw':state=E.newLife(crypto.getRandomValues(new Uint32Array(1))[0],{market:$('#market').value,rareMode:$('#rarity').value});category='All';expanded=false;break;
 case 'confirm-new':{const input=$('#new-seed').value,seed=input===''?crypto.getRandomValues(new Uint32Array(1))[0]:Number(input);if(!Number.isInteger(seed)||seed<0||seed>4294967295){toast('Use a whole-number seed from 0 to 4,294,967,295.');return;}state=E.newLife(seed,{market:$('#new-market').value,rareMode:$('#new-rarity').value});view='play';currentBeforeArchive=null;category='All';expanded=false;closeModal();break;}
 case 'reroll':state=E.newLife(crypto.getRandomValues(new Uint32Array(1))[0],{market:state.market,rareMode:state.rareMode});break;
 case 'start':E.startLife(state);break;
 case 'focus':if(state.status==='plan'){state.plan.focus=b.dataset.id;render();}return;
 case 'category':category=b.dataset.id;render();return;
 case 'expand':expanded=!expanded;render();return;
 case 'action':{const a=E.actionById(state,b.dataset.id);if(!E.toggleAction(state,a.id)){toast(E.actionStatus(state,a)||'Not enough time or spending money. Remove an activity to make room.');return;}render();return;}
 case 'commit':if(!E.commitPlan(state)){toast('Please check your activity budget and eligibility.');return;}break;
 case 'choice':E.chooseEvent(state,Number(b.dataset.index));break;
 case 'continue':E.continueReaction(state);break;
 case 'next':E.nextPhase(state);category='All';expanded=false;break;
 case 'repair':E.settle(state);break;
 case 'save-academic':{if(state.status!=='plan')return;const c=E.context(state);state.plan.load=Number($('#course-load').value);state.exchangeChoice=Number($('#exchange-semester').value);state.exchangeCity=$('#exchange-city').value;const primary=$('#primary-major');if(primary&&!primary.disabled&&primary.value!==state.major){if(primary.value==='Entrepreneurship, Design and Innovation'&&(E.gpa(state)||0)<3){toast('EDI selection uses a fictional 3.00 GPA screen.');return;}state.major=primary.value;state.flags.majorLocked=true;}const type=$('#secondary-type'),subject=$('#secondary-subject');if(!type.disabled&&(type.value!==state.secondary||!state.secondary&&type.value)){if(!E.setSecondary(state,type.value,subject.value)){toast('This combination or declaration is not available. EDI/AMPB/QFin use a fictional 3.00 screen.');return;}}closeModal();render();toast('Study plan saved. Exchange still needs a winter application activity.');return;}
 case 'read-life':if(view!=='archive')currentBeforeArchive=state;state=JSON.parse(JSON.stringify(archive[Number(b.dataset.index)]));view='archive';closeModal();break;
 case 'return-current':state=currentBeforeArchive;currentBeforeArchive=null;view='play';break;
 default:return;
 }render(true);if(act==='commit'||act==='continue')$('#story-title')?.focus({preventScroll:true});});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
